import React, { useEffect, useState } from "react";
import Log from "./utils/logger";

function App() {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState("All");
  const [viewed, setViewed] = useState({});

  // 🔹 priority score
  const getScore = (item) => {
    let score = 0;

    if (item.type === "Placement") score += 3;
    else if (item.type === "Result") score += 2;
    else score += 1;

    score += new Date(item.timestamp).getTime();

    return score;
  };

  useEffect(() => {
    const getData = async () => {
      try {
        Log("frontend", "info", "api", "getting notifications");

        const response = await fetch(
          "http://20.207.122.201/evaluation-service/notifications",
          {
            headers: {
              Authorization: `Bearer YOUR_TOKEN_HERE`
            }
          }
        );

        const result = await response.json();

        let sorted = result.notifications.sort(
          (a, b) => getScore(b) - getScore(a)
        );

        setData(sorted);
        setLoading(false);

        Log("frontend", "info", "api", "data received");

      } catch (e) {
        console.log("API failed → using fallback data");

        // 🔹 fallback (IMPORTANT)
        const fallback = {
          notifications: [
            {
              id: "1",
              type: "Result",
              message: "mid-sem",
              timestamp: "2026-04-22 17:51:30"
            },
            {
              id: "2",
              type: "Placement",
              message: "CSX Corporation hiring",
              timestamp: "2026-04-22 17:51:18"
            },
            {
              id: "3",
              type: "Event",
              message: "farewell",
              timestamp: "2026-04-22 17:51:06"
            }
          ]
        };

        setData(fallback.notifications);
        setLoading(false);
      }
    };

    getData();
  }, []);

  // 🔹 filter
  const filteredData =
    filter === "All" ? data : data.filter((item) => item.type === filter);

  // 🔹 top 3
  const topNotifications = data.slice(0, 3);

  // 🔹 mark viewed
  const handleClick = (id) => {
    setViewed({ ...viewed, [id]: true });
  };

  return (
    <div style={{ padding: "20px", fontFamily: "Arial" }}>
      <h2>📢 Notifications</h2>

      {/* FILTER */}
      <div style={{ marginBottom: "15px" }}>
        {["All", "Placement", "Result", "Event"].map((type) => (
          <button
            key={type}
            onClick={() => setFilter(type)}
            style={{
              marginRight: "10px",
              padding: "6px 12px",
              background: filter === type ? "#333" : "#ddd",
              color: filter === type ? "#fff" : "#000",
              border: "none",
              borderRadius: "5px",
              cursor: "pointer"
            }}
          >
            {type}
          </button>
        ))}
      </div>

      {loading ? (
        <p>Loading...</p>
      ) : (
        <>
          {/* PRIORITY */}
          <h3>⭐ Priority Notifications</h3>
          {topNotifications.map((item) => (
            <div
              key={item.id}
              style={{
                border: "1px solid #ccc",
                padding: "10px",
                marginBottom: "8px",
                borderRadius: "6px",
                background: "#fff8e1"
              }}
            >
              <b>{item.type}</b> - {item.message}
            </div>
          ))}

          {/* ALL */}
          <h3>📄 All Notifications</h3>
          {filteredData.map((item) => (
            <div
              key={item.id}
              onClick={() => handleClick(item.id)}
              style={{
                border: "1px solid #ccc",
                padding: "10px",
                marginBottom: "8px",
                borderRadius: "6px",
                cursor: "pointer",
                background: viewed[item.id] ? "#e0e0e0" : "#ffffff"
              }}
            >
              <b>{item.type}</b> - {item.message}
              <br />
              <small>{item.timestamp}</small>
            </div>
          ))}
        </>
      )}
    </div>
  );
}

export default App;
